mapper.select:
SELECT A.BOOK_DATE AS bookDate, /**记账日期（入账日期）**/ A.VOUCH_NUM AS vouchNum, /**记账流水号（凭证编号）**/ A.BOOKSET_ID AS booksetId, /**账套代码**/ C.BOOKSET_NAME AS booksetName, /**账套名称**/ B.BUSI_ID AS busiId, /**资产/负债代码（业务明细代码）**/ D.FINPROD_ABBR AS finprodAbbr, /**资产/负债名称（金融产品简称）**/ B.SUBJECT_NO AS subjectNo, /**科目号**/ E.SUBJECT_NAME AS subjectName, /**科目名称**/ B.CD_FLAG AS cdFlag, /**借贷方向**/ E.BAL_FLAG AS balFlag,/**余额方向**/ B.CCY AS ccy, /**币种**/ B.HAPPEN_AMT AS happenAmt, /**发生额**/ B.HAPPEN_AMT AS balance, /**余额金额**/ /**UAT-241 查询结果中“发生数量”、“发生额”、“余额金额”三列的升降序排列功能颠倒，点升序排列但是按照降序排列，点降序排列但是按升序排列 add by leipeng 20180903*/ nvl(B.HAPPEN_NUMBER,0) AS happenNumber, /**发生数量**/ A.TRADE_ID AS tradeId, /**业务编码（交易编号）**/ A.COM_TABLE_ID AS comTableId /**业务类别（合并场景代码）*/ FROM bok_VOUCH_MAIN A LEFT JOIN bok_VOUCH_DETAIL B ON A.VOUCH_NUM = B.VOUCH_NUM /**凭证子表**/ INNER JOIN BOK_BOOKSET C ON A.BOOKSET_ID = C.BOOKSET_ID /**账套表**/ LEFT JOIN FIN_PRODUCT D ON D.FINPROD_ID = B.BUSI_ID /**标的类金融产品(金融产品代码=业务明细代码)**/ INNER JOIN BOK_SUBJECT E ON E.BOOKSET_ID = C.BOOKSET_ID_TMPL AND B.SUBJECT_NO = E.SUBJECT_NO /**账套科目表**/ WHERE 1=1
AND A.COM_TABLE_ID IN
#{item}
AND C.BOOKSET_Id IN
#{item}
AND B.SUBJECT_NO IN
#{item}
AND upper(B.BUSI_ID) LIKE '%'||upper(#{busiId})||'%'
AND B.CCY=#{ccy}
AND A.BOOK_DATE >= #{bookDateBegin}
AND A.BOOK_DATE <= #{bookDateEnd}
ORDER BY A.BOOK_DATE DESC,A.VOUCH_NUM DESC

SELECT A.BOOK_DATE AS bookDate, /**记账日期（入账日期）**/ A.VOUCH_NUM AS vouchNum, /**记账流水号（凭证编号）**/ A.BOOKSET_ID AS booksetId, /**账套代码**/ C.BOOKSET_NAME AS booksetName, /**账套名称**/ B.BUSI_ID AS busiId, /**资产/负债代码（业务明细代码）**/ D.FINPROD_ABBR AS finprodAbbr, /**资产/负债名称（金融产品简称）**/ B.SUBJECT_NO AS subjectNo, /**科目号**/ E.SUBJECT_NAME AS subjectName, /**科目名称**/ B.CD_FLAG AS cdFlag, /**借贷方向**/ E.BAL_FLAG AS balFlag,/**余额方向**/ B.CCY AS ccy, /**币种**/ B.HAPPEN_AMT AS happenAmt, /**发生额**/ B.HAPPEN_AMT AS balance, /**余额金额**/ /**UAT-241 查询结果中“发生数量”、“发生额”、“余额金额”三列的升降序排列功能颠倒，点升序排列但是按照降序排列，点降序排列但是按升序排列 add by leipeng 20180903*/ nvl(B.HAPPEN_NUMBER,0) AS happenNumber, /**发生数量**/ A.TRADE_ID AS tradeId, /**业务编码（交易编号）**/ A.COM_TABLE_ID AS comTableId, /**业务类别（合并场景代码）*/ A.BUS_VOUCHNUM AS busVouchnum /**凭证编号*/ FROM bok_VOUCH_MAIN A LEFT JOIN bok_VOUCH_DETAIL B ON A.VOUCH_NUM = B.VOUCH_NUM /**凭证子表**/ INNER JOIN BOK_BOOKSET C ON A.BOOKSET_ID = C.BOOKSET_ID /**账套表**/ LEFT JOIN FIN_PRODUCT D ON D.FINPROD_ID = B.BUSI_ID /**标的类金融产品(金融产品代码=业务明细代码)**/ INNER JOIN BOK_SUBJECT E ON E.BOOKSET_ID = C.BOOKSET_ID_TMPL AND B.SUBJECT_NO = E.SUBJECT_NO /**账套科目表**/ WHERE C.BOOKSET_TYPE = #{booksetType}
AND A.COM_TABLE_ID IN
#{comTableId}
AND C.BOOKSET_Id IN
#{booksetId}
AND B.SUBJECT_NO IN
#{subjectNo}
AND upper(B.BUSI_ID) LIKE '%'||upper(#{busiId})||'%'
AND B.CCY=#{ccy}
AND A.BOOK_DATE >= #{bookDateBegin}
AND A.BOOK_DATE <= #{bookDateEnd}
ORDER BY A.BOOK_DATE DESC,A.VOUCH_NUM DESC
